<template>
  <v-dialog
    :model-value="modelValue"
    :max-width="maxWidth"
    :persistent="persistent || busy"
    scrollable
    @update:model-value="onToggle"
  >
    <div class="dw-dialog" role="dialog" aria-modal="true" :aria-labelledby="titleId" :aria-busy="busy ? 'true' : 'false'">
      <div class="dw-dialog__head">
        <div v-if="icon" class="dw-dialog__icon" :class="{ 'dw-dialog__icon--danger': danger }">
          <v-icon :icon="icon" size="20" />
        </div>
        <div class="dw-dialog__titles">
          <h2 :id="titleId" class="dw-dialog__title">{{ title }}</h2>
          <div v-if="subtitle || $slots.subtitle" class="dw-dialog__sub">
            <slot name="subtitle">{{ subtitle }}</slot>
          </div>
        </div>
        <button type="button" class="icon-btn" aria-label="Close dialog" :disabled="busy" @click="close">
          <v-icon icon="mdi-close" />
        </button>
      </div>
      <div class="dw-dialog__body">
        <slot />
      </div>
      <div v-if="$slots.footer" class="dw-dialog__foot">
        <slot name="footer" />
      </div>
    </div>
  </v-dialog>
</template>

<script>
let uid = 0;

// Shared dialog shell: same header, close button, spacing and footer everywhere.
export default {
  name: "DwDialog",
  props: {
    modelValue: { type: Boolean, default: false },
    title: { type: String, required: true },
    subtitle: { type: String, default: "" },
    icon: { type: String, default: "" },
    danger: { type: Boolean, default: false },
    maxWidth: { type: [Number, String], default: 520 },
    persistent: { type: Boolean, default: false },
    busy: { type: Boolean, default: false }, // blocks closing while an API call runs
  },
  emits: ["update:modelValue", "close"],
  data() {
    return { titleId: `dw-dialog-title-${++uid}` };
  },
  methods: {
    onToggle(v) {
      if (!v) this.close();
    },
    close() {
      if (this.busy) return;
      this.$emit("update:modelValue", false);
      this.$emit("close");
    },
  },
};
</script>

<style scoped>
.dw-dialog__titles {
  flex: 1;
  min-width: 0;
}
</style>
