<template>
  <DwDialog
    :model-value="modelValue"
    :title="title"
    :icon="danger ? 'mdi-alert-outline' : icon"
    :danger="danger"
    :busy="busy"
    max-width="440"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <p class="confirm-msg">
      <slot>{{ message }}</slot>
    </p>
    <template #footer>
      <button type="button" class="btn-outline" :disabled="busy" @click="$emit('update:modelValue', false)">
        {{ cancelLabel }}
      </button>
      <button
        type="button"
        :class="[danger ? 'btn-danger' : 'btn-primary', { 'btn-busy': busy }]"
        :disabled="busy"
        @click="$emit('confirm')"
      >
        <span v-if="busy" class="dw-spinner" aria-hidden="true" />
        {{ busy ? busyLabel : confirmLabel }}
      </button>
    </template>
  </DwDialog>
</template>

<script>
import DwDialog from "./DwDialog.vue";

// Accessible confirmation for destructive or irreversible actions (NFR-04).
// The parent closes it after the action succeeds, so errors can be shown in place.
export default {
  name: "ConfirmDialog",
  components: { DwDialog },
  props: {
    modelValue: { type: Boolean, default: false },
    title: { type: String, required: true },
    message: { type: String, default: "" },
    confirmLabel: { type: String, default: "Confirm" },
    busyLabel: { type: String, default: "Working…" },
    cancelLabel: { type: String, default: "Cancel" },
    icon: { type: String, default: "mdi-help-circle-outline" },
    danger: { type: Boolean, default: false },
    busy: { type: Boolean, default: false },
  },
  emits: ["update:modelValue", "confirm"],
};
</script>

<style scoped>
.confirm-msg {
  margin: 0;
  color: var(--dw-text-2);
  font-size: var(--dw-fs-base);
  line-height: var(--dw-lh);
  overflow-wrap: anywhere;
}
</style>
