// People search for the Share dialog. Uses the same federated search query as the
// native 3DEXPERIENCE Share panel: active Person objects matched on username, full
// name, first name or last name.

import http from "./httpClient.js";
import initApp from "@/utils/initApp";
import { PLATFORM, SHARING } from "@/config/platformConfig";
import { firstText, toArray } from "@/utils/searchResult";


// Strip characters that have a meaning in the search query syntax.
const tokensOf = (text) =>
  String(text || "")
    .replace(/[()[\]{}"'\\*?:^~!&|<>=+/,;]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 4);

const FIELDS = ["ds6w:identifier", "ds6wg:fullname", "firstname", "lastname"];

export function buildPeopleQuery(text) {
  const tokens = tokensOf(text);
  if (!tokens.length) return "";
  const perToken = tokens.map((t) => "(" + FIELDS.map((f) => `[${f}]:(*${t}*)`).join(" OR ") + ")");
  return `[ds6w:type]:"Person" AND ${perToken.join(" AND ")} AND policycurrent:"Person.Active"`;
}

export function mapPeople(json) {
  return toArray(json?.results)
    .map((r) => {
      const login = firstText(r, "ds6w:identifier");
      const firstName = firstText(r, "firstname");
      const lastName = firstText(r, "lastname");
      const name = firstText(r, "ds6wg:fullname") || firstText(r, "ds6w:label") || [firstName, lastName].filter(Boolean).join(" ");
      return {
        id: firstText(r, "resourceid"),
        login,
        name,
        firstName,
        lastName,
        personId: login ? login + SHARING.personIdSuffix : "",
      };
    })
    .filter((p) => p.id && p.login);
}

export default {
  async search(text, limit = 20) {
    const query = buildPeopleQuery(text);
    if (!query || String(text).trim().length < 2) return [];
    const store = initApp.store();
    const json = await http.post(PLATFORM.federatedSearch, {
      with_indexing_date: false,
      with_nls: false,
      label: `dw-share-people-${Date.now()}`,
      locale: "en",
      select_predicate: ["ds6w:label", "ds6w:identifier", "ds6wg:fullname", "firstname", "lastname"],
      select_file: [],
      query,
      login: { "3dspace": { SecurityContext: initApp.getCTX() } },
      order_by: "desc",
      order_field: "relevance",
      nresults: limit,
      start: "0",
      source: ["3dspace"],
      tenant: store.getServer,
    });
    return mapPeople(json);
  },
};
